import math
a, b, c = 1, 2, 5
d = b * b - 4 * a * c
if d < 0:
    print("no real roots")
elif d == 0:
    print("one root:", -b / (2 * a))
else:
    print("two roots:", (-b + math.sqrt(d)) / (2 * a), (-b - math.sqrt(d)) / (2 * a))
